mapper.select:
		SELECT EXISTS (
    		SELECT 1
    		FROM reviews
    		WHERE user_id = #{userId}
    		AND spot_id = #{spotId}
		)

mapper.update:
		UPDATE reviews
        SET rating = #{rating}, comment = #{comment}, updated_at = CURRENT_TIMESTAMP
		WHERE user_id = #{userId}
		AND spot_id = #{spotId}

mapper.delete:
DELETE FROM reviews
WHERE user_id = #{userId}
AND spot_id = #{spotId}

mapper.select:
SELECT r.id, s.spot_name, u.username, r.rating, r.comment, r.created_at FROM reviews r LEFT JOIN spots s ON r.spot_id = s.id LEFT JOIN users u ON r.user_id = u.id
WHERE r.comment LIKE CONCAT('%', #{keyword}, '%') OR s.name LIKE CONCAT('%', #{keyword}, '%') OR u.username LIKE CONCAT('%', #{keyword}, '%') OR u.display_name LIKE CONCAT('%', #{keyword}, '%')
ORDER BY r.id LIMIT #{limit} OFFSET #{offset}
